<?php
declare(strict_types=1);
define('SAAS_NO_GLOBAL_NAV',true); require_once __DIR__.'/finance.php'; require_finance_admin();
$pdo=db();$message=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=(string)$_POST['transaction_type'];$in=$type==='Income'?(float)$_POST['amount']:0;$out=$type==='Expense'?(float)$_POST['amount']:0;$pdo->beginTransaction();$previous=(float)$pdo->query('SELECT running_balance FROM cash_flow ORDER BY date DESC,id DESC LIMIT 1')->fetchColumn();$balance=$previous+$in-$out;$pdo->prepare('INSERT INTO cash_flow(date,transaction_type,category,description,money_in,money_out,running_balance,reference,created_by) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$_POST['date'],$type,$_POST['category'],trim((string)$_POST['description']),$in,$out,$balance,trim((string)($_POST['reference']??'')),$_SESSION['user']['id']]);$pdo->commit();$message='Cash-flow entry saved.';}
$rows=$pdo->query('SELECT * FROM cash_flow ORDER BY date,id')->fetchAll();function e(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
