Owner In-Out</option></select></div><div class="col-md-2"><label>Amount</label><input class="form-control" type="number" step="0.01" name="amount" required></div><div class="col-md-3"><label>Reference</label><input class="form-control" name="reference"></div><div class="col-12"><label>Description</label><input class="form-control" name="description" required></div><div><button class="btn-indigo">Add entry</button></div></div></form><section class="saas-card"><table class="saas-table"><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Description</th><th>In</th><th>Out</th><th>Balance</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['date'])?></td><td><?=e($row['transaction_type'])?></td><td><?=e($row['category'])?></td><td><?=e($row['description'])?></td><td><?=inr($row['money_in'])?></td><td><?=inr($row['money_out'])?></td><td><?=inr($row['running_balance'])?></td></tr><?php endforeach;?></tbody></table></section></main></div></body></html>
